    "?OMBRE_BRAIN_SOURCE_DIR=$OMBRE_BRAIN_SOURCE_DIR_DEFAULT"
    "?OMBRE_BRAIN_VENV=$OMBRE_BRAIN_VENV_DEFAULT"
    "?OMBRE_BUCKETS_DIR=$OMBRE_BUCKETS_DIR_DEFAULT"
    "?OMBRE_BRAIN_IMAGE=$OMBRE_BRAIN_IMAGE_DEFAULT"
