filter_obsidian_memory_from_config() {
  local file="$1"
  local tmp_filter
  tmp_filter="$(mktemp)"
  awk '
    /^mcp_servers:/ { in_mcp=1 }
    in_mcp && /^  obsidian_memory:/ { skip=1; next }
    in_mcp && skip && /^  [^ ]/ { skip=0 }
    in_mcp && skip { next }
    /^platform_toolsets:/ { in_pt=1 }
    in_pt && /mcp-obsidian_memory/ { next }
    { print }
  ' "$file" >| "$tmp_filter"
  "${SUDO[@]}" cp "$tmp_filter" "$file"
  rm -f "$tmp_filter"
}

filter_ombre_memory_from_config() {
  local file="$1"
  local tmp_filter
  tmp_filter="$(mktemp)"
  awk '
    /^mcp_servers:/ { in_mcp=1 }
    in_mcp && /^  ombre_memory:/ { skip=1; next }
    in_mcp && /^  ombre_memory_extra:/ { skip=1; next }
    in_mcp && skip && /^  [^ ]/ { skip=0 }
    in_mcp && skip { next }
    /^platform_toolsets:/ { in_pt=1 }
    in_pt && /mcp-ombre_memory/ { next }
    in_pt && /mcp-ombre_memory_extra/ { next }
    { print }
  ' "$file" >| "$tmp_filter"
  "${SUDO[@]}" cp "$tmp_filter" "$file"
  rm -f "$tmp_filter"
}

write_lite_runtime_config() {
  log "refreshing lite runtime config"
  install_file_portable 644 "$REPO_ROOT/hermes/profile/config.lite.yaml" "$LITE_HOME/config.yaml"
  install_file_portable 644 "$REPO_ROOT/hermes/profile/config.lite.yaml" "$LITE_HOME/profiles/$LITE_PROFILE/config.yaml"
  filter_ombre_memory_from_config "$LITE_HOME/config.yaml"
  filter_ombre_memory_from_config "$LITE_HOME/profiles/$LITE_PROFILE/config.yaml"
  if [ "${OBSIDIAN_MEMORY_MCP_ENABLED:-false}" = "false" ]; then
    filter_obsidian_memory_from_config "$LITE_HOME/config.yaml"
    filter_obsidian_memory_from_config "$LITE_HOME/profiles/$LITE_PROFILE/config.yaml"
  fi
  chown_if_user_exists "$LITE_HOME"
}

write_full_runtime_config() {
  local profile_config="$FULL_HOME/profiles/$FULL_PROFILE/config.yaml"
  local runtime_config="$FULL_HOME/config.yaml"
  local tmp

  log "refreshing full runtime config"
  if ! "${SUDO[@]}" test -f "$profile_config"; then
    echo "ERROR: missing installed full profile config: $profile_config" >&2
    exit 1
  fi

  tmp="$(mktemp)"
  cat >| "$tmp" <<EOF
# Generated by scripts/apply-hermes-runtime-split.sh.
# Secrets stay in .env files; this file contains runtime shape only.

model:
  provider: deepseek
  default: $MODEL_NAME
  model: $MODEL_NAME
  base_url: https://api.deepseek.com/v1
  api_mode: chat_completions

web:
  search_backend: tavily
  extract_backend: tavily

compression:
  enabled: true
  threshold: 0.35
  target_ratio: 0.12
  protect_last_n: 8
  hygiene_hard_message_limit: 160

auxiliary:
  compression:
    provider: main
    model: ''
    base_url: null
  web_extract:
    provider: main
    model: ''
    base_url: null
  session_search:
    provider: main
    model: ''
    base_url: null

terminal:
  backend: local
  cwd: /opt/ran_agent
  timeout: 180
  lifetime_seconds: 300

disabled_tools:
  - browser_vision
  - image_generate
  - text_to_speech
  - video_analyze
  - vision_analyze
  - terminal
  - file
  - sticker_save_from_inbox
  - sticker_update
  - sticker_delete

platform_toolsets:
  cli:
    - web
    - skills
    - memory
    - session_search
    - safe
    - mcp-time
    - mcp-social_reader
    - mcp-media_reader
    - mcp-search_hub
    - mcp-co_reading
    - mcp-sticker_catalog
    - mcp-media_generation
    - mcp-personal_memory
    - mcp-obsidian_memory
    - mcp-ombre_memory
    - mcp-ombre_memory_extra
    - mcp-playwright
  gateway:
    - web
    - skills
    - memory
    - session_search
    - safe
    - mcp-time
    - mcp-social_reader
    - mcp-media_reader
    - mcp-search_hub
    - mcp-co_reading
    - mcp-sticker_catalog
    - mcp-media_generation
    - mcp-personal_memory
    - mcp-obsidian_memory
    - mcp-ombre_memory
    - mcp-ombre_memory_extra
    - mcp-playwright

EOF

  "${SUDO[@]}" awk 'BEGIN { copy=0 } /^mcp_servers:/ { copy=1 } copy { print }' "$profile_config" >> "$tmp"
  if ! "${SUDO[@]}" grep -Eq '^  tavily:' "$profile_config"; then
    cat >> "$tmp" <<'EOF'

  tavily:
    url: "https://mcp.tavily.com/mcp/?tavilyApiKey=${TAVILY_API_KEY}"
    timeout: 60
    connect_timeout: 30
EOF
  fi

  if [ "${OBSIDIAN_MEMORY_MCP_ENABLED:-false}" = "false" ]; then
    filter_obsidian_memory_from_config "$tmp"
  fi
  if ! ombre_mcp_should_be_exposed; then
    if ombre_brain_enabled && bool_is_true "$(effective_env_value OMBRE_BRAIN_MCP_ENABLED "$OMBRE_BRAIN_MCP_ENABLED_DEFAULT")"; then
      log "WARNING: Ombre Brain runner is not available; omitting direct Ombre MCP from full Hermes config"
    fi
    filter_ombre_memory_from_config "$tmp"
  fi

  install_file_portable 644 "$tmp" "$runtime_config"
  chown_if_user_exists "$runtime_config"
  rm -f "$tmp"
}

